create extension if not exists pgcrypto;
create or replace function set_updated() returns trigger language plpgsql as $$
begin new.updated_at=now(); new.version=coalesce(old.version,0)+1; return new; end $$;

create table profiles(id uuid primary key references auth.users on delete cascade, full_name text, avatar_url text, created_at timestamptz default now());
create table families(id uuid primary key default gen_random_uuid(), name text not null, currency text not null default 'IDR', timezone text not null default 'Asia/Jakarta', created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table family_members(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, user_id uuid not null references auth.users on delete cascade, role text not null check(role in('owner','admin','member','viewer')), created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz, created_by uuid, unique(family_id,user_id));
create table family_invitations(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, role text not null check(role in('admin','member','viewer')), token_hash text not null unique, status text not null default 'pending' check(status in('pending','accepted','revoked')), expires_at timestamptz not null default now()+interval '7 days', created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1);

create table wallets(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, name text not null, kind text not null check(kind in('cash','bank','ewallet','savings','investment','credit_card','other')), initial_balance numeric(18,2) not null default 0, currency text not null default 'IDR', color text, icon text, is_active boolean default true, description text, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz, unique(id,family_id));
create table categories(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, name text not null, type text not null check(type in('income','expense')), parent_id uuid references categories, icon text, color text, description text, is_active boolean default true, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz, unique(id,family_id));
create table debts(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, direction text not null check(direction in('payable','receivable')), counterparty text not null, principal numeric(18,2) not null check(principal>0), due_date date, status text not null default 'open' check(status in('open','paid','overdue')), notes text, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table recurring_transactions(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, type text not null check(type in('income','expense')), wallet_id uuid not null references wallets, category_id uuid not null references categories, amount numeric(18,2) not null check(amount>0), description text, frequency text not null check(frequency in('daily','weekly','monthly','yearly')), interval_n int not null default 1 check(interval_n>0), start_date date not null, end_date date, is_active boolean default true, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table debt_payments(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, debt_id uuid not null references debts, amount numeric(18,2) not null check(amount>0), paid_on date not null, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table transactions(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade,
 type text not null check(type in('income','expense','transfer')), date date not null, amount numeric(18,2) not null check(amount>0),
 wallet_id uuid not null, to_wallet_id uuid, category_id uuid references categories on delete restrict, description text, note text,
 parent_transaction_id uuid references transactions, recurring_id uuid references recurring_transactions, occurrence_date date, debt_payment_id uuid references debt_payments, idempotency_key text,
 created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz,
 foreign key(wallet_id,family_id) references wallets(id,family_id), foreign key(to_wallet_id,family_id) references wallets(id,family_id),
 check((type='transfer' and to_wallet_id is not null and to_wallet_id<>wallet_id and category_id is null) or (type<>'transfer' and to_wallet_id is null and category_id is not null)),
 unique(recurring_id,occurrence_date), unique(family_id,idempotency_key));
create index on transactions(family_id,date); create index on transactions(family_id,wallet_id,date); create index on transactions(family_id,category_id,date);
create table budgets(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, scope text not null check(scope in('category','wallet')), category_id uuid references categories, wallet_id uuid references wallets, period_type text not null check(period_type in('weekly','monthly','yearly','custom')), start_date date not null, end_date date not null, amount numeric(18,2) not null check(amount>0), created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz, check((scope='category' and category_id is not null) or (scope='wallet' and wallet_id is not null)));
create table assets(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, name text not null, kind text not null, acquisition_value numeric(18,2) not null default 0, current_value numeric(18,2) not null default 0, purchased_on date, notes text, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table asset_valuations(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, asset_id uuid not null references assets, value numeric(18,2) not null, valued_on date not null, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1);
create table attachments(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, transaction_id uuid references transactions, asset_id uuid references assets, debt_id uuid references debts, storage_path text not null, mime_type text not null, size_bytes int not null, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, deleted_at timestamptz);
create table notifications(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, user_id uuid not null, kind text not null, title text not null, body text, read_at timestamptz, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1);
create table settings(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, key text not null, value jsonb, created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), version int default 1, unique(family_id,key));
create table audit_logs(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, actor uuid, action text not null, table_name text not null, record_id uuid, diff jsonb, created_at timestamptz default now());
create table idempotency_keys(id uuid primary key default gen_random_uuid(), family_id uuid not null references families on delete cascade, key text not null, created_at timestamptz default now(), unique(family_id,key));

do $$ declare t text; begin
 foreach t in array array['families','family_members','family_invitations','wallets','categories','debts','recurring_transactions','debt_payments','transactions','budgets','assets','asset_valuations','attachments','notifications','settings'] loop
  execute format('create trigger trg_upd before update on %I for each row execute function set_updated()',t);
 end loop; end $$;

create or replace function audit() returns trigger language plpgsql security definer set search_path=public as $$
declare r record; begin r:=coalesce(new,old);
 insert into audit_logs(family_id,actor,action,table_name,record_id,diff) values(r.family_id,auth.uid(),tg_op,tg_table_name,r.id,case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end);
 return r; end $$;
do $$ declare t text; begin
 foreach t in array array['wallets','categories','transactions','budgets','debts','debt_payments','assets','recurring_transactions','family_members'] loop
  execute format('create trigger trg_audit after insert or update or delete on %I for each row execute function audit()',t);
 end loop; end $$;

create or replace function check_tx_family() returns trigger language plpgsql as $$
begin if new.category_id is not null and not exists(select 1 from categories c where c.id=new.category_id and c.family_id=new.family_id and c.type=new.type) then
  raise exception 'Kategori tidak valid untuk keluarga/tipe ini' using errcode='23514'; end if; return new; end $$;
create trigger trg_chk before insert or update on transactions for each row execute function check_tx_family();
